@import "tailwindcss";
@import "uniwind";

/* ─── Theme tokens ──────────────────────────────────────────────────── */
/*
 * World Scenery (T3 Pretty's default look): alpine-nature tones ported from
 * apps/web/src/scenery/worldSceneryTheme.ts. Keep hues in step with that
 * palette — greens carry the identity; text/icon steps preserve the original
 * mobile contrast ladder. Feature colors with no scenery equivalent (danger,
 * inline skills, backdrops) keep their upstream values.
 */
@layer theme {
  :root {
    @variant android {
      --font-mono: "monospace";
    }

    @variant light {
      /* Page backgrounds */
      --color-screen: #f4f6f4;
      --color-sheet: rgba(244, 246, 244, 0.98);
      --color-sheet-solid: #f4f6f4;

      /* Card / surface */
      --color-card: #ffffff;
      --color-card-alt: #fafcfa;
      --color-card-translucent: rgba(255, 255, 255, 0.8);

      /* Text */
      --color-foreground: #161a17;
      --color-foreground-secondary: #414843;
      --color-foreground-muted: #5a625b;
      --color-foreground-tertiary: #7c837d;

      /* Borders & separators */
      --color-border: rgba(22, 38, 26, 0.1);
      --color-border-subtle: rgba(22, 38, 26, 0.07);
      --color-separator: rgba(22, 38, 26, 0.05);

      /* Subtle backgrounds (badges, pills, overlays) */
      --color-subtle: rgba(39, 99, 63, 0.06);
      --color-subtle-strong: rgba(39, 99, 63, 0.11);
      --color-inline-skill-background: rgba(217, 70, 239, 0.12);
      --color-inline-skill-border: rgba(217, 70, 239, 0.25);
      --color-inline-skill-foreground: #a21caf;

      /* Primary action */
      --color-primary: #27633f;
      --color-primary-foreground: #ffffff;
      --color-primary-shadow: #1c4630;

      /* Secondary action */
      --color-secondary: #ffffff;
      --color-secondary-foreground: #232823;
      --color-secondary-border: rgba(22, 38, 26, 0.1);
      --color-switch-active-track: #2e7d4f;
      --color-switch-active-thumb: #ffffff;
      --color-switch-inactive-track: rgba(22, 38, 26, 0.1);
      --color-switch-inactive-thumb: #7c837d;

      /* Danger */
      --color-danger: #fef2f2;
      --color-danger-border: rgba(239, 68, 68, 0.12);
      --color-danger-foreground: #c22030;

      /* Inputs */
      --color-input: #ffffff;
      --color-input-border: rgba(22, 38, 26, 0.12);
      --color-sidebar-search: rgba(118, 128, 118, 0.12);
      --color-placeholder: #6b736c;

      /* Icons */
      --color-icon: #232823;
      --color-icon-muted: #3f473f;
      --color-icon-subtle: #7c837d;

      /* Header / glass chrome */
      --color-header: rgba(244, 246, 244, 0.97);
      --color-header-border: rgba(22, 38, 26, 0.07);
      --color-glass-surface: rgba(255, 255, 255, 0.72);
      --color-glass-tint: rgba(255, 255, 255, 0.18);
      /* Desktop scenery chrome is 42–52% over the pre-blurred photo. */
      --color-chrome-glass: rgba(255, 255, 255, 0.52);
      --color-chrome-glass-border: rgba(22, 38, 26, 0.1);

      /* StatusBar */
      --color-status-bar: #f4f6f4;

      /* Markdown */
      --color-md-body: #141815;
      --color-md-strong: #060907;
      --color-md-link: #1d5f8a;
      --color-md-blockquote-border: rgba(22, 38, 26, 0.1);
      --color-md-blockquote-bg: rgba(39, 99, 63, 0.03);
      --color-md-code-bg: rgba(39, 99, 63, 0.06);
      --color-md-code-text: #242925;
      --color-md-user-code-bg: rgba(255, 255, 255, 0.22);
      --color-md-user-code-text: #ffffff;
      --color-md-user-fence-bg: rgba(0, 0, 0, 0.16);
      --color-md-user-fence-text: #ffffff;
      --color-md-hr: rgba(22, 38, 26, 0.1);

      /* iMessage-style user bubble */
      --color-user-bubble: #27633f;
      --color-user-bubble-foreground: #ffffff;
      --color-user-bubble-foreground-muted: rgba(255, 255, 255, 0.78);
      --color-user-bubble-skill-foreground: #f0abfc;

      /* Drawer / modal backdrop */
      --color-backdrop: rgba(10, 20, 13, 0.22);
      --color-drawer: rgba(250, 252, 250, 0.99);
      --color-drawer-shadow: rgba(10, 20, 13, 0.12);

      /* Misc */
      --color-dot-separator: rgba(22, 38, 26, 0.2);
      --color-wordmark: #232823;
      --color-chevron: rgba(22, 38, 26, 0.22);
    }

    @variant dark {
      /* Page backgrounds */
      --color-screen: #0e1110;
      --color-sheet: rgba(14, 17, 16, 0.98);
      --color-sheet-solid: #0e1110;

      /* Card / surface */
      --color-card: #131715;
      --color-card-alt: #161b18;
      --color-card-translucent: rgba(19, 23, 21, 0.8);

      /* Text */
      --color-foreground: #f0f2ef;
      --color-foreground-secondary: #b6bcb7;
      --color-foreground-muted: #98a29a;
      --color-foreground-tertiary: #6e7770;

      /* Borders & separators */
      --color-border: rgba(222, 236, 226, 0.08);
      --color-border-subtle: rgba(222, 236, 226, 0.05);
      --color-separator: rgba(222, 236, 226, 0.04);

      /* Subtle backgrounds (badges, pills, overlays) */
      --color-subtle: rgba(145, 201, 163, 0.07);
      --color-subtle-strong: rgba(145, 201, 163, 0.13);
      --color-inline-skill-background: rgba(217, 70, 239, 0.12);
      --color-inline-skill-border: rgba(217, 70, 239, 0.25);
      --color-inline-skill-foreground: #f0abfc;

      /* Primary action */
      --color-primary: #91c9a3;
      --color-primary-foreground: #0c1710;
      --color-primary-shadow: #000000;

      /* Secondary action */
      --color-secondary: rgba(145, 201, 163, 0.07);
      --color-secondary-foreground: #e6eae6;
      --color-secondary-border: rgba(222, 236, 226, 0.08);
      --color-switch-active-track: #7fbc93;
      --color-switch-active-thumb: #ffffff;
      --color-switch-inactive-track: rgba(222, 236, 226, 0.08);
      --color-switch-inactive-thumb: #8e948f;

      /* Danger */
      --color-danger: rgba(251, 106, 118, 0.14);
      --color-danger-border: rgba(251, 106, 118, 0.18);
      --color-danger-foreground: #ffd2d7;

      /* Inputs */
      --color-input: #1a201c;
      --color-input-border: rgba(222, 236, 226, 0.1);
      --color-sidebar-search: rgba(118, 128, 120, 0.24);
      --color-placeholder: #b3bcb5;

      /* Icons */
      --color-icon: #e8ece9;
      --color-icon-muted: #b0b9b2;
      --color-icon-subtle: #8e948f;

      /* Header / glass chrome */
      --color-header: rgba(14, 17, 16, 0.97);
      --color-header-border: rgba(222, 236, 226, 0.08);
      --color-glass-surface: rgba(19, 23, 21, 0.78);
      --color-glass-tint: rgba(27, 33, 29, 0.24);
      --color-chrome-glass: rgba(19, 23, 21, 0.52);
      --color-chrome-glass-border: rgba(222, 236, 226, 0.1);

      /* StatusBar */
      --color-status-bar: #0e1110;

      /* Markdown */
      --color-md-body: #e4e7e4;
      --color-md-strong: #f0f2ef;
      --color-md-link: #6cb8e8;
      --color-md-blockquote-border: rgba(222, 236, 226, 0.12);
      --color-md-blockquote-bg: rgba(145, 201, 163, 0.05);
      --color-md-code-bg: rgba(222, 236, 226, 0.07);
      --color-md-code-text: #e4e7e4;
      --color-md-user-code-bg: rgba(255, 255, 255, 0.18);
      --color-md-user-code-text: #ffffff;
      --color-md-user-fence-bg: rgba(0, 0, 0, 0.28);
      --color-md-user-fence-text: #ffffff;
      --color-md-hr: rgba(222, 236, 226, 0.1);

      /* iMessage-style user bubble */
      --color-user-bubble: #24422f;
      --color-user-bubble-foreground: #f2f4f1;
      --color-user-bubble-foreground-muted: rgba(242, 244, 241, 0.78);
      --color-user-bubble-skill-foreground: #f0abfc;

      /* Drawer / modal backdrop */
      --color-backdrop: rgba(0, 0, 0, 0.48);
      --color-drawer: rgba(12, 15, 13, 0.99);
      --color-drawer-shadow: rgba(0, 0, 0, 0.32);

      /* Misc */
      --color-dot-separator: rgba(222, 236, 226, 0.2);
      --color-wordmark: #e8ece9;
      --color-chevron: rgba(222, 236, 226, 0.2);
    }
  }
}

/* ─── Typography ────────────────────────────────────────────────────── */
@theme {
  /* Keep these native family names aligned with app.config.ts. */
  --font-sans: "DMSans-Regular";
  --font-medium: "DMSans-Medium";
  --font-bold: "DMSans-Bold";

  /* Keep this scale aligned with src/lib/typography.ts for native style props. */
  --text-3xs: 11px;
  --text-3xs--line-height: 14px;
  --text-2xs: 12px;
  --text-2xs--line-height: 16px;
  --text-xs: 13px;
  --text-xs--line-height: 17px;
  --text-sm: 14px;
  --text-sm--line-height: 19px;
  --text-base: 16px;
  --text-base--line-height: 23px;
  --text-lg: 18px;
  --text-lg--line-height: 23px;
  --text-xl: 21px;
  --text-xl--line-height: 28px;
  --text-2xl: 26px;
  --text-2xl--line-height: 32px;
  --text-3xl: 30px;
  --text-3xl--line-height: 36px;
}

/* ─── Custom utilities ──────────────────────────────────────────────── */
@utility font-t3-medium {
  font-family: var(--font-medium);
}

@utility font-t3-bold {
  font-family: var(--font-bold);
}

@utility font-t3-extrabold {
  font-family: var(--font-bold);
  font-weight: 800;
}
